import React, {useState} from 'react';
import {Button, Card, message, Space, Steps, theme} from "antd";
import {Config} from "../../../conf";
import {
    DeploymentUnitOutlined,
    HighlightOutlined,
    ScissorOutlined,
    SkinOutlined,
    SmileOutlined
} from "@ant-design/icons";


const CreateCharacter : React.FC = () => {
    const steps = [
        {
            title: 'Генетика',
            content: '',
            icon: <DeploymentUnitOutlined />
        },
        {
            title: 'Форма лица',
            content: '',
            icon: <SmileOutlined />
        },
        {
            title: 'Волосы',
            content: '',
            icon: <ScissorOutlined />
        },
        {
            title: 'Особенности кожи',
            content: '',
            icon: <HighlightOutlined />
        },
        {
            title: 'Одежда',
            content: '',
            icon: <SkinOutlined />
        },
    ];
    const [current,setCurrent] = useState<number>(0)


    return (
        <Space direction={"vertical"} style={{position:'absolute',width:Config.screenResolution.width, height:Config.screenResolution.height, alignItems: 'stretch'}}>
            <Card>
                <Steps items={steps} current={current}/>
            </Card>
            <Card style={{width:330}}>

            </Card>
        </Space>
    );
};

export default CreateCharacter;
